import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.D4fUSYzX.js";const m=JSON.parse(`{"title":"ADR 0010: Model discovery queries the agent's own CLI","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0010-model-discovery-through-the-agent-cli.md","filePath":"adr/0010-model-discovery-through-the-agent-cli.md"}`),s={name:"adr/0010-model-discovery-through-the-agent-cli.md"};function o(r,e,d,l,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0010-model-discovery-queries-the-agent-s-own-cli" tabindex="-1">ADR 0010: Model discovery queries the agent&#39;s own CLI <a class="header-anchor" href="#adr-0010-model-discovery-queries-the-agent-s-own-cli" aria-label="Permalink to &quot;ADR 0010: Model discovery queries the agent&#39;s own CLI&quot;">​</a></h1><p>Status: accepted Date: 2026-09-02</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR 0009 resolves model and thinking level per handoff, but the factory cannot see which models an agent offers: model names are not portable across agent kinds, and a bad value dies inside the agent. The control plane is documented as agent-agnostic: it talks to herdr, git, and the GitHub CLI, never to the agent runtime itself.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The command runner gains a model list query. For the pi kind it runs the agent&#39;s own CLI (<code>pi --list-models</code>) and reads the models the runtime reports as available; the runtime lists only usable models, so provider auth is already applied. The list serves three places: startup validation of the config&#39;s model values that name a determinate agent (the model each Task profile resolves to, which carries the <code>default-model</code> leg of its chain, and each Consultation type&#39;s model; the rest are checked at handoff time), the override panel (the Model row offers the selected agent&#39;s list), and the setting fit check at handoff time (an unfit model or thinking level fails the handoff with a readable reason before the agent starts). When no list can be fetched, the check is skipped and the agent&#39;s own rejection stands.</p><p>Thinking levels form one shared standard set (off, minimal, low, medium, high, xhigh, max). Each agent type declares the non-empty subset it supports, and free-text levels are retired.</p><h2 id="considered-alternatives" tabindex="-1">Considered alternatives <a class="header-anchor" href="#considered-alternatives" aria-label="Permalink to &quot;Considered alternatives&quot;">​</a></h2><ul><li>Declare the model list in the config file, like <code>thinking-values</code>. Rejected: it drifts from reality as models ship, vanish, or lose auth, and the config would certify models the agent no longer offers.</li><li>A declarative list-models command per agent type in the config. Rejected: only one kind has a list command today. The runner maps the kind to the CLI, and a declarative layer can follow when a second kind needs it.</li><li>Check fit only at handoff time, as ADR 0009 had it. Rejected: a config error should be seen at startup, not mid-ticket, and the override panel needs the list regardless.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The control plane now talks to the agent runtime directly, not only through herdr. The command runner stays the single egress, and the tests fake it.</li><li>The runner is agent-kind aware by design. An unknown kind fails with a reason, and every consumer degrades: no list means a free-text Model row and a skipped fit check.</li><li>The <code>pi --list-models</code> table shape is a pinned contract on the installed pi version. A layout change degrades to the no-list path with a warning, not a crash.</li><li>A handoff that would have started and died inside the agent now fails in the factory with a readable reason, and the ticket stays open. This refines ADR 0009&#39;s &quot;checked by the agent itself&quot;: the factory pre-checks when a list is available, and the agent&#39;s rejection still stands when it is not.</li><li>A provider without auth reads as an unknown model, because the runtime lists only usable models. The startup error hints at checking auth.</li><li>A Model list value is one argument cell, end to end. The parser refuses a row whose value carries whitespace, and the start command substitutes a setting value inside its own template token instead of splitting the substituted string. A model can therefore never become an argument plus a stray positional the agent reads as its model.</li><li>The query carries its own short timeout rather than the handoff&#39;s ten-minute budget, because it runs before the first frame at boot, on every override panel open, and inside the observation cycle. A hung agent CLI degrades to the no-list path in seconds; the free-text Model row and the skipped model check are that path.</li></ul>',11)])])}const f=t(s,[["render",o]]);export{m as __pageData,f as default};
